import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] raw = new long[n];
        for (int i = 0; i < n; i++) raw[i] = nextLong();
        long[] s = raw.clone();
        Arrays.sort(s);
        int u = 0;
        for (int i = 0; i < n; i++) if (i == 0 || s[i] != s[i - 1]) s[u++] = s[i];
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = Arrays.binarySearch(s, 0, u, raw[i]);
        long rank = ((long) n * (n + 1) / 2 + 1) / 2;
        int lo = 1, hi = u;
        int[] counts = new int[u];
        // smallest k such that at least rank subarrays have at most k distinct values
        while (lo < hi) {
            int k = (lo + hi) / 2, distinct = 0, left = 0;
            Arrays.fill(counts, 0);
            long total = 0;
            for (int right = 0; right < n; right++) {
                if (counts[a[right]]++ == 0) distinct++;
                while (distinct > k)
                    if (--counts[a[left++]] == 0) distinct--;
                total += right - left + 1;
