            if (total >= rank) hi = k;
            else lo = k + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	raw := make([]int, n)
	for i := range raw {
		raw[i] = next()
	}
	s := append([]int(nil), raw...)
	sort.Ints(s)
	u := 0
	for i := range s {
		if i == 0 || s[i] != s[i-1] {
			s[u] = s[i]
			u++
		}
	}
	s = s[:u]
	a := make([]int, n)
	for i, x := range raw {
		a[i] = sort.SearchInts(s, x)
	}
	rank := (n*(n+1)/2 + 1) / 2
	lo, hi := 1, u
	counts := make([]int, u)
	// smallest k such that at least rank subarrays have at most k distinct values
	for lo < hi {
		k := (lo + hi) / 2
		clear(counts)
		distinct, left, total := 0, 0, 0
		for right := 0; right < n; right++ {
			if counts[a[right]] == 0 {
				distinct++
			}
			counts[a[right]]++
			for distinct > k {
				counts[a[left]]--
				if counts[a[left]] == 0 {
					distinct--
				}
				left++
			}
			total += right - left + 1
		}
		if total >= rank {
			hi = k
		} else {
			lo = k + 1
		}
	}
	fmt.Println(lo)
}
